/* eslint-disable no-console */
const fs = require('fs');
const path = require('path');
const { spawnSync } = require('child_process');
const { isEntryPoint } = require('./lib/entry-point.js');

/**
 * sync-service-management-cana-bundle — vendor the Cana browser bundle into
 * the zero-build Service Management SPA (JUM-484).
 *
 * The SPA boots Cana as its SOLE designer store and resolves the bare
 * `@jumentix/cana` specifier through the import map in `index.html`, which
 * points at `apps/service-management/vendor/cana/index.js`. That file is a
 * browser ESM bundle (`bun build --format esm --target browser`) — a copy
 * vendored into the app, not a symlink, because server.js
 * containment-validates every served path against the app root. The
 * vendored file is gitignored; this script regenerates it, and the browser
 * integration suites run it before booting the server, so a stale or absent
 * bundle can never read as a designer outage.
 *
 * The bundle is built from `packages/cana/src/adapter.ts` — the module that
 * DEFINES `createCanaDatabaseClient`, the one binding the SPA imports — not
 * from the package index: bun 1.3.14's full-graph bundling of
 * `packages/cana/src/index.ts` emits dangling export bindings (renamed
 * `x2` references with no top-level definition) that WebKit refuses to link
 * at all. The artifact check below fails closed if the required binding is
 * exported but not defined, pinning against exactly that class of bundler
 * regression.
 */

const CANA_SOURCE_ENTRY = path.join('packages', 'cana', 'src', 'adapter.ts');
const CANA_DIST_FILE = path.join('packages', 'cana', 'dist', 'service-management-cana.mjs');
const VENDORED_FILE = path.join('apps', 'service-management', 'vendor', 'cana', 'index.js');

/** The one binding the SPA imports from the bundle (designerStoreFactory). */
const REQUIRED_BINDING = 'createCanaDatabaseClient';

const VENDORED_HEADER = '/* Vendored Cana ESM bundle (JUM-484). Generated by'
  + ' ci-cd/sync-service-management-cana-bundle.js from packages/cana — do not edit. */\n';

function syncServiceManagementCanaBundle(options = {}) {
  const root = options.root || process.cwd();
  const spawn = options.spawn || spawnSync;
  const exists = options.exists || fs.existsSync;
  const readFile = options.readFile || fs.readFileSync;
  const writeFile = options.writeFile || ((target, contents) => {
    fs.mkdirSync(path.dirname(target), { recursive: true });
    fs.writeFileSync(target, contents);
  });
  const logger = options.logger || console;

  const sourceEntry = path.join(root, CANA_SOURCE_ENTRY);
  if (!exists(sourceEntry)) {
    logger.error(`[ci] cana bundle sync: source entry not found: ${sourceEntry}`);
    return 1;
  }

  // `bun build` is the pinned bundler for the browser artifact (packages/cana
  // build:esm); under Node the bun binary resolves from PATH.
  const bunExecutable = path.basename(process.execPath).startsWith('bun') ? process.execPath : 'bun';
  const distFile = path.join(root, CANA_DIST_FILE);
  const build = spawn(bunExecutable, [
    'build', sourceEntry,
    '--outfile', distFile,
    '--format', 'esm',
    '--target', 'browser'
  ], { cwd: root, stdio: 'inherit' });
  if (build.status !== 0) {
    logger.error(`[ci] cana bundle sync: bun build failed with status ${String(build.status)}.`);
    return build.status || 1;
  }
  if (!exists(distFile)) {
    logger.error(`[ci] cana bundle sync: build reported success but ${distFile} is missing.`);
    return 1;
  }

  // Fail closed on a dangling export (bundler renamed the binding away from
  // its definition): exported-but-undefined bindings make WebKit reject the
  // whole module at link time, which would read as a designer outage.
  const artifact = readFile(distFile, 'utf-8');
  const defined = new RegExp(`(async\\s+)?function\\s+${REQUIRED_BINDING}\\b`).test(artifact)
    || new RegExp(`(const|let|var|class)\\s+${REQUIRED_BINDING}\\b`).test(artifact);
  if (!defined) {
    logger.error(`[ci] cana bundle sync: ${REQUIRED_BINDING} is not defined in the built artifact.`);
    return 1;
  }

  const target = path.join(root, VENDORED_FILE);
  writeFile(target, VENDORED_HEADER + artifact);
  logger.log(`[ci] cana bundle synced: ${path.relative(root, target)}`);
  return 0;
}

if (isEntryPoint(module)) {
  process.exitCode = syncServiceManagementCanaBundle();
}

module.exports = {
  CANA_DIST_FILE,
  CANA_SOURCE_ENTRY,
  REQUIRED_BINDING,
  VENDORED_FILE,
  VENDORED_HEADER,
  syncServiceManagementCanaBundle
};
